import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第54章 一百四十块","description":"","frontmatter":{},"headers":[],"relativePath":"第54章_一百四十块.md","filePath":"第54章_一百四十块.md"}'),o={name:"第54章_一百四十块.md"};function r(n,p,s,c,i,l){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第54章-一百四十块" tabindex="-1">第54章 一百四十块 <a class="header-anchor" href="#第54章-一百四十块" aria-label="Permalink to &quot;第54章 一百四十块&quot;">​</a></h1><p>那年我第一次自己挣到钱，是一百四十块。</p><p>不是我爸妈给的，不是我奖学金。是我替她发货，从中间抽出来的。</p><p>这件事是她先提出来的。</p><p>那天她说，你现在帮我发六单，一单我给你五块。</p><p>我说，不用。</p><p>她说，你必须拿。</p><p>我说，为什么。</p><p>她说，因为你白干，你就觉得你欠我。</p><p>她说，你要是收了钱，你就是办事的。</p><p>她说，办事的人心里是平的。</p><p>我说，你想让我心里平？</p><p>她说，我想让你别觉得自己 low。</p><p>她说，你老觉得自己 low，你说话就老是绕。</p><p>我看完这一段，坐在桌前很久。</p><p>她这个人很怪。她从来不安慰我。</p><p>她不安慰的方式，是给我一件具体的事，让我用干活的方式跟她站平。</p><p>那天开始我记账。</p><p>我记账不是因为我要钱。我记账是因为我这辈子只会这个。</p><p>我拿一张纸，画了四栏：日期，寄出，收入，支出。</p><p>三十七天里，我发了十九单。</p><p>收了一百四十块零五毛。发货抽成是九十五块，剩下四十五块是我替三个人跑了四趟腿，一件十块。那五毛我没记，因为它是别人找零找错了，我留下会睡不着。</p><p>我不说这个数挣得少。</p><p>我那年身上从来没有超过两百块现金。</p><p>这一百四对我来说是很大的数。</p><p>因为我可以拿它算东西。</p><p>五月末有一天夜里，我在纸上算了一整页。</p><p>我算的不是路费。路费我算过，算完发现我买不起，就不算了。</p><p>我算的是别的。</p><p>我第一行写的是时差。</p><p>她那边跟这边是同一个钟点。我们两个隔的不是时差，是她家里那一屋子人。</p><p>第二行：她一周能上线一次，一次二十分钟。</p><p>第三行：一年五十二周。</p><p>我算出来五百二十个二十分钟，是一千零四十分钟。</p><p>十七个小时。</p><p>一年，十七个小时。</p><p>我看着这个数，觉得它已经很惨了。</p><p>然后我把它除下去。</p><p>我说，一句话八秒。</p><p>十七个小时是六万一千二百秒。</p><p>一年我能跟她说七千六百五十句话。</p><p>我在那个数字底下画了两道横线。</p><p>七千六百五十。</p><p>我算得很准，因为这个除法我小学就会。</p><p>我又往下算了一段。</p><p>如果我说一句话平均要她想三秒才回，那这句话的成本就是十一秒。</p><p>一年能撑起来的来回，是五千六百多次。</p><p>一个人一年跟我说话五千六百次，很多。</p><p>五千六百次里，我要拿多少去说&quot;你今天吃饭了吗&quot;。</p><p>我在纸上列了一张清单，把我要说的话分成三类。</p><p>第一类：不能让她知道的。</p><p>第二类：她问了我要装的。</p><p>第三类：可以说的。</p><p>第三类我写了很久，写了四条。</p><p>一条是天气，一条是我妈，一条是我那个搪瓷杯，一条是驿站那个小伙子。</p><p>那天夜里十一点半，我把这张纸折起来，压在书底下。</p><p>我去洗了脸。</p><p>回来的时候我看见她上线了。</p><p>她说，你在算什么。</p><p>我说，算一个东西。</p><p>她说，算什么。</p><p>我说，算我能不能买得起一样东西。</p><p>她说，你买什么。</p><p>我说，一张卡。</p><p>她说，什么卡。</p><p>我说，能打长途的。</p><p>她说，你打长途干什么，我们有网。</p><p>我说，网有时候没有。</p><p>她说，你什么时候用得上。</p><p>我说，有一天你会用到。</p><p>她隔了一会儿。</p><p>她说，你说话越来越像谜语。</p><p>我说，我在省钱。</p><p>她说，省多少。</p><p>我说，一百四。</p><p>她说，一百四能干什么。</p><p>我说，能买一张卡，能寄四趟东西。</p><p>她说，寄给谁。</p><p>我说，寄给你。</p><p>那天晚上她没接这一句。</p><p>六月，她跟我说她要清房间。</p><p>她说，我要出国，我有一堆东西带不走。</p><p>她说，我妈说全扔。</p><p>她说，我说我找个地方寄。</p><p>她说，她说你寄给谁。</p><p>她说，我说我同学。</p><p>她说，她说你哪个同学。</p><p>她说，我没答。</p><p>然后她发了一句。</p><p>她说，你能收吗。</p><p>我说，能。</p><p>她说，我那儿有三十多件。</p><p>她说，立牌、徽章、色纸、一大袋子别人不要的小卡。</p><p>她说，还有两个娃娃，很大，你可能要买个大箱子。</p><p>我说，都寄过来。</p><p>她说，你疯了？</p><p>她说，我说是三十多件，很重。</p><p>我说，都寄过来。</p><p>她说，你为什么答应得这么快。</p><p>我坐在那儿，看着这一句。</p><p>因为我算过的那个东西，就在这一句上面。</p><p>我跟她一年只能说七千六百五十句话。</p><p>可是我替她收三十件东西，每一件都要拆开、要防潮、要上架、要编号。</p><p>那是三十件东西，不是七千六百五十句里的一句。</p><p>我说，我答应得快，是因为这个我能做到。</p><p>她说，这个怎么就能做到了。</p><p>我说，这个不用说话。</p><p>她那天晚上最后一条，隔了很久。</p><p>她说，行。</p><p>她说，那我下周寄。</p><p>她说，你先别高兴，你要负责保管。</p><p>我说，我知道。</p><p>她说，你不知道。</p><p>她说，保管的意思是不能丢，不能卖，不能跟任何人说这是我的。</p><p>我说，我知道。</p><p>她说，你再说一遍。</p><p>我说，不能丢，不能卖，不能说是你的。</p><p>她说，好。</p><p>她说，那你现在是我这边的仓库。</p><p>那晚我下线之前，在纸上那一页的底下写了一行。</p><p>我写：仓库不需要说话。</p><p>第一个箱子是七月六号到的。</p><p>很大，比我整个人高一半。快递小哥把它卸在我家楼下，问我要不要上楼。</p><p>我说，要。</p><p>他说，你这箱子多少钱的货。</p><p>我说，不值钱。</p><p>他说，不值钱你买这么大。</p><p>我把箱子拖上楼，拖到楼梯中间那个拐的时候，我坐在上面喘了一会儿。</p><p>那天中午我把箱子放在床底下。</p><p>我把里面的东西一件一件拿出来摆在地上。</p><p>立牌用硬纸分开，徽章一枚一枚垫上纸，色纸按大小分成三摞，那一大袋小卡我没有数，我只把袋口用橡皮筋扎了两道。</p><p>两个娃娃很大，我把它们放在柜子顶上，背面朝墙。</p><p>我忙了一个中午，热出一背镶的汗。</p><p>摆完我坐在地上看了一遍。</p><p>那天下午我妈推开我房门。</p><p>她手里拿着一个盆，她来收衣服。</p><p>她一进来就看见了地上那个塑封袋。</p><p>她把盆放下，蹲下去拿起来看。</p><p>她说，这是什么。</p><p>我说，同学的东西。</p><p>她说，同学的东西放我们家地上。</p><p>我说，他们家搬不了。</p><p>她看着我。</p><p>她说，你同学家在哪。</p><p>我说，挺远的。</p><p>她说，多远。</p><p>我说，特别远。</p><p>她把那个袋子放回地上，拿脚把它踢到床底下去。</p><p>她说，收好，别让你爸看见，他说闲东西。</p><p>我说，好。</p><p>她走出去以前又在门口站了一下。</p><p>她说，你那个同学，是不是那个不出来的。</p><p>我没说话。</p><p>她说，我不问。</p><p>她说，你自己心里有个数就行。</p><p>那天晚上我把床底下的箱子又开了一次。</p><p>我把那三十多件东西按她发给我的一张单子对了一遍，一件一件打勾。</p><p>对完我在最下面写了四个字。</p><p>我写：一件不少。</p><p>第二天早上我妈在桌上放了两块钱，让我去买盐。</p><p>我去了。</p><p>我回来的时候把那两块钱找零的钢镚儿放在桌上，放得很整齐。</p><p>我那天什么都没说。</p><p>我身上有一百四十块，和一个已经寄到的三十件仓库。</p>',164)])])}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
